excels.excel:

EXPORT WITH SHEET="设备点检记录填报表", HEADER=true,
    MAPPING={"a":"设备编号","b":"设备名称","c":"点检人","d":"运行时长","e":"温度","f":"点检结论","g":"备注"},
    FORMAT={"d":"0","e":"0.0"},
    FORMULAS={
        D8:'SUM(D2:D7)'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    }
